#include <Wire.h>
#include <Adafruit_SSD1306.h>

const int SENSOR = A0;
const int DRY = 520;  // the reading in dry air
const int WET = 260;  // the reading in a glass of water
Adafruit_SSD1306 screen(128, 64, &Wire);

void setup() {
  Serial.begin(9600);
  screen.begin(SSD1306_SWITCHCAPVCC, 0x3C);  // 0x3C is the screen's I²C address
  screen.setTextColor(SSD1306_WHITE);
}

void loop() {
  int raw = analogRead(SENSOR);
  int moisture = map(raw, DRY, WET, 0, 100);  // turn the reading into 0-100 %
  moisture = constrain(moisture, 0, 100);
  Serial.println(moisture);

  screen.clearDisplay();
  screen.setTextSize(3);
  screen.setCursor(0, 0);
  screen.print(moisture);
  screen.print("%");
  screen.drawRect(0, 28, 128, 8, SSD1306_WHITE);
  screen.fillRect(0, 28, moisture * 128 / 100, 8, SSD1306_WHITE);

  // smaller text for the message
  screen.setTextSize(2);
  screen.setCursor(0, 46);
  if (moisture < 30) {
    screen.print("Water me!");
  } else if (moisture > 85) {
    screen.print("Too wet!");
  } else {
    screen.print("Happy :)");
  }
  screen.display();
  delay(500);
}
